          const tile = m.v === 2 ? C.signal : C.ink;
          ctx.fillStyle = rgba(tile, t);
          ctx.fillRect(x + 0.5, y + 0.5, cw - 1, ch - 1);
          const h = hash(cx, cy, tick + (near > 0.2 ? Math.floor(time * 12) : 0));
          ctx.fillStyle = m.v === 2 ? rgba(C.ink, 0.55 * t) : rgba(C.paper, 0.38 * t);
          ctx.fillText(RAMP[5 + (h > 0.5 ? 1 : 0)], x + tx, y + ty);
          if (t >= 1) continue;
